```ts
  /** The unpersisted half of `markWorkerDeadLocked`: identity check, stop, locator cleared into
   * `resumeSessionFile`. Returns the claim it retired, or undefined for a stale locator. Callers
   * persist — `markWorkerDeadLocked` at once (the prompt-failure breaker), `markWorkerDead` after
   * its relaunch decision, so the cleared locator and the counted failure are one durable write. */
  private async retireDeadWorkerLocatorLocked(
    token: string,
    locator: Locator
  ): Promise<WorkerRoleClaim | undefined> {
    const current = this.deps.state.roles[token];
    if (!current || !("issue" in current) || !sameProcess(current.locator, locator)) {
      return undefined;
    }
    await this.retireWorkerLocator(token, locator);
    const resumeSessionFile = current.locator?.ompSessionFile ?? current.resumeSessionFile;
    delete current.locator;
    if (resumeSessionFile) current.resumeSessionFile = resumeSessionFile;
    return current;
  }

  private async markWorkerDeadLocked(token: string, locator: Locator): Promise<boolean> {
    const retired = await this.retireDeadWorkerLocatorLocked(token, locator);
    if (!retired) return false;
    await this.persist();
    return true;
  }
